"use strict";function query(n){$.ajax({url:_global.root+"applicants/index",dataType:"html",method:"POST",data:{FullName:$("#FullName").val(),PositionId:$("#PositionId").val(),Status:$("#Status").val(),FromDate:$("#FromDate").val(),ToDate:$("#ToDate").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#applicants-detail").html(n);floatThead("table#data")},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteApplicant(n){confirm("Are you sure you want to delete this applicant?",function(){$.post(_global.root+"applicants/Delete",{id:n},function(t){t.IsSuccessful?($("#row"+n).remove(),autoIndex()):alert(t.Message)})})}$(document).ready(function(){$("#FullName").keyup(function(n){n.keyCode===13&&query(!1)});$("#submit").on("click",function(){query(!1)});if(query(!0),$(".form-create-edit").length>0){initAutocomplete("#Recruiter","#RecruiterId",null);let n=$("#successed").val();n==="true"&&confirm('<i class="icon-success mdi mdi-checkbox-marked-circle-outline"><\/i><p>Successfull!<\/p><p>Press OK to continue<\/p>',function(){document.location=_global.root+"Applicants/Index"})}});